from pathlib import Path
import base64

def decoded(value):
    return base64.b64decode(value).decode()

motion_path = Path("godot/motion.gd")
text = motion_path.read_text()
old_publish = decoded("CXJlc3VsdC5kZW5zZV9vdXRwdXQgPSB7CgkJIm1heF9raW5lbWF0aWNfZGVmZWN0X21wcyI6IF9tZWFzdXJlX2RlbnNlX2RlZmVjdChyZXN1bHQpLAoJfQo=")
new_publish = decoded("CXJlc3VsdC5kZW5zZV9vdXRwdXQgPSBfbWVhc3VyZV9kZW5zZV9vdXRwdXQocmVzdWx0KQo=")
if text.count(old_publish) != 1:
    raise SystemExit(f"expected one dense-output publication block, found {text.count(old_publish)}")
text = text.replace(old_publish, new_publish)
marker = decoded("CgpzdGF0aWMgZnVuYyBfbWVhc3VyZV9kZW5zZV9kZWZlY3QodHJhamVjdG9yeTogRGljdGlvbmFyeSkgLT4gZmxvYXQ6")
marker_at = text.find(marker)
if marker_at < 0:
    raise SystemExit("dense defect function marker was not found")
if not text.rstrip().endswith("return maximum"):
    raise SystemExit("dense defect function is no longer the final source block")
replacement = decoded("")
motion_path.write_text(text[:marker_at] + replacement)

tests_path = Path("godot/motion_tests.gd")
tests = tests_path.read_text()
old_test = decoded("CXZhciBraW5lbWF0aWNfZGVmZWN0OiBmbG9hdCA9IHJvdXRlLmRlbnNlX291dHB1dC5nZXQoIm1heF9raW5lbWF0aWNfZGVmZWN0X21wcyIsIElORikKCV9leHBlY3Qoa2luZW1hdGljX2RlZmVjdCA+PSAwLjAgYW5kIGtpbmVtYXRpY19kZWZlY3QgPD0gMC4wMDAwMSwKCQkiZGVuc2Ugb3V0cHV0IG1lYXN1cmVzIGl0cyBhY3R1YWwgZHIvZHQgbWludXMgcmV0dXJuZWQgdlQgZGVmZWN0IikK")
new_test = decoded("")
if tests.count(old_test) != 1:
    raise SystemExit(f"expected one stale dense-output assertion, found {tests.count(old_test)}")
tests_path.write_text(tests.replace(old_test, new_test))
